const body = $input.first().json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Invalid event body');
const allowed = ['application.created', 'jobs.matched', 'admin.summary', 'scraper.warning', 'scraper.stale'];
const type = body.event_type || 'application.created';
if (!allowed.includes(type)) throw new Error('Unsupported event type');
if (typeof body.event_id !== 'string' || !/^baalebos-[a-zA-Z0-9-]{1,140}$/.test(body.event_id)) throw new Error('Invalid event identifier');
const to = body.to_email || body.employer_email;
if (typeof to !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) throw new Error('Invalid event recipient');
let subject = body.subject;
let text = body.text;
if (type === 'application.created' && !subject && !text) {
  if (!Number.isInteger(body.application_id) || body.application_id < 1 || typeof body.job_title !== 'string') throw new Error('Invalid application event');
  subject = 'New application: ' + body.job_title;
  text = 'A new application was received for ' + body.job_title + '.\nApplication ID: ' + body.application_id + '\nReview it at https://www.baalebo.xyz/hr';
}
if (typeof subject !== 'string' || !subject.trim() || subject.length > 500 || typeof text !== 'string' || !text.trim() || text.length > 20000) throw new Error('Invalid email content');
return [{json:{event_id:body.event_id, idempotency_key:type === 'application.created' ? 'application-notification-' + body.event_id : body.event_id, to, subject:subject.replace(/[\r\n]/g, ' '), text}}];

const result = $input.first().json;
if (typeof result.id !== 'string' || !result.id) throw new Error('Email provider did not accept the message');
return [{json:{id:result.id}}];
